// The option registry model. Internal: not exported from package:bugsee_flutter.
//
// The DATA is `option_registry.g.dart`, generated by scripts/generate_options.dart from the
// manifests the two SDKs publish (test/fixtures/option_manifests). This file only gives it a
// shape and lookups. Nothing here is hand-copied from an SDK.

/// The platforms the plugin runs on.
enum OptionPlatform { android, ios }

/// The SDK's own declared type of an option (manifest `type`).
enum OptionType { boolean, int, float, string, enumeration, map, list }

/// One platform's registration of an option.
final class PlatformOption {
  const PlatformOption({
    required this.module,
    required this.defaultValue,
    this.enumName,
    this.enumValues,
    this.deprecatedSince,
  });

  /// The artifact that registers it (`bugsee-android`, `bugsee-android-ndk`, `Bugsee`, ...).
  final String module;

  /// The SDK's default; for an enum the constant NAME (never its value); `null` means the
  /// option has no default.
  final Object? defaultValue;

  /// The SDK's name for the enum, and its constants by INTERNAL value (never ordinal).
  final String? enumName;
  final Map<String, Object>? enumValues;

  final String? deprecatedSince;
}

/// One option as the SDKs register it.
final class OptionSpec {
  const OptionSpec({
    required this.key,
    required this.type,
    required this.hidden,
    required this.typed,
    this.enumFamily,
    this.android,
    this.ios,
  });

  /// The full key, `com.bugsee.option...`.
  final String key;
  final OptionType type;

  /// Internal (`$$`) options are not public surface and never appear in uploaded `sdk.options`.
  final bool hidden;

  /// Whether `BugseeOptions` has a typed field for it (public, and of a bundled module).
  final bool typed;

  /// The Dart enum the option's values come from, when it is an enum option.
  final String? enumFamily;

  final PlatformOption? android;
  final PlatformOption? ios;

  PlatformOption? on(OptionPlatform platform) =>
      platform == OptionPlatform.android ? android : ios;
}
